/* @lc app=leetcode id=3583 lang=kotlin */ class Solution { fun specialTriplets(nums: IntArray): Int = 1_000_000_007L.let { M -> HashMap<Int, Int>().let { l -> HashMap<Int, Int>().also { r -> nums.forEach { r.merge(it, 1) { a, b -> a + b } } }.let { r -> nums.fold(0L) { acc, x -> r.merge(x, -1) { a, b -> a + b }.let { ((l[2 * x] ?: 0).toLong() * (r[2 * x] ?: 0) + acc) % M }.also { l.merge(x, 1) { a, b -> a + b } } }.toInt() } } } }